import { isFeatureEnabled } from "@/lib/features";
import { coordinatorNoteCanRead, coordinatorSudCanRead } from "./coordinatorSudAccess";
import { chartPart2Basis } from "./chartPart2Boundary";
import { consentGate, PROGRAM_RECIPIENTS } from "./consentGate";
// §4 — Acting staff role + record-class RBAC matrix.
// Additive layer on top of the existing persona routing; never replaces it.

import { useSyncExternalStore } from "react";
import {
  AdelanteEHR,
  type ConsentCategory,
  type GroupCategory,
  type Patient,
  type ProgressNote,
} from "./ehr";

export type StaffRole =
  | "ecm_provider"
  // §v3.0 role architecture — Correctional Facility Care Manager. Works the
  // pre-release D90→0 countdown inside/with the facility; distinct from the
  // ECM Provider, whose D0–90 program clock starts AT release. Deliberately
  // given a thin record-class grant list: their surface is the CF task list /
  // Reentry Care Plan (Phase 2), not the full chart.
  | "cf_care_manager"
  | "sud_counselor"
  | "clinical_trainee"
  | "medical_assistant"
  | "peer_specialist"
  // §v3.0 Phase 3 — Community Health Worker. Non-licensed community-based
  // role that documents CHW services (G0019/G0022) billed through an
  // enrolled supervising provider; see SUPERVISION_REQUIRED_ROLES below.
  | "community_health_worker"
  | "therapist"
  | "pmhnp"
  // Physician (psychiatrist / medical director). Holds every clinical
  // permission the PMHNP holds — resolved through `permissionRole()`.
  | "physician"
  // §Batch E1 — outpatient nursing. Draft — pending clinical sign-off.
  | "nurse_rn"
  | "lvn"
  | "billing"
  | "clinical_coordinator"
  | "intake_coordinator"
  | "credentialing_coordinator"
  | "billing_coordinator"
  | "sys_admin";

export const STAFF_ROLES: { key: StaffRole; label: string }[] = [
  { key: "ecm_provider", label: "ECM Provider" },
  { key: "cf_care_manager", label: "CF Care Manager" },
  { key: "sud_counselor", label: "SUD Counselor" },
  { key: "clinical_trainee", label: "Clinical Trainee" },
  { key: "medical_assistant", label: "Medical Assistant" },
  { key: "peer_specialist", label: "Peer specialist" },
  { key: "community_health_worker", label: "Community Health Worker" },
  { key: "therapist", label: "Therapist" },
  { key: "physician", label: "Physician (psychiatrist / medical director)" },
  { key: "pmhnp", label: "PMHNP" },
  { key: "nurse_rn", label: "Nurse (RN)" },
  { key: "lvn", label: "LVN" },
  { key: "billing", label: "Billing coordinator" },
  { key: "clinical_coordinator", label: "Clinical coordinator" },
  { key: "intake_coordinator", label: "Intake Coordinator" },
  { key: "credentialing_coordinator", label: "Credentialing coordinator" },
  { key: "billing_coordinator", label: "Billing coordinator (expanded)" },
  { key: "sys_admin", label: "System admin" },
];

export type RecordClass =
  | "account_support"
  | "demographics"
  | "screeners_mh"
  | "screeners_sud"
  | "psych_eval"
  | "care_plan"
  | "therapy_notes"
  | "meds_erx"
  | "telehealth_room"
  | "sdoh"
  | "self_help"
  // §Adelante Journey Phase 7 — patient-authored Stanley-Brown safety plan.
  // Its own class, NOT `self_help` and NOT `therapy_notes`: it is clinical-
  // adjacent risk-management content a crisis responder may need to read
  // during an active concern, but it is authored by the patient, so it must
  // not inherit the write semantics of clinician documentation.
  | "safety_plan"
  | "sud_treatment"
  // §ASCMI stricter tier — see PSYCHOTHERAPY_NOTES_TIER note below.
  | "psychotherapy_notes"
  | "case_notes"
  | "peer_notes"
  // §v3.0 Phase 3 — CHW service documentation. Its own class (not `peer_notes`)
  // because the two roles bill under different HCPCS families and neither
  // should be able to author the other's record.
  | "chw_notes"
  | "documents"
  | "billing"
  | "consent_ledger"
  | "problems"
  | "allergies"
  | "alerts"
  | "eligibility"
  | "care_coordination"
  | "custody_tracking"
  // §Pre-release build 5 — WHO OWNS THE PRE-RELEASE WORKSPACE.
  //
  // Replaces the old generic `custody_tracking` gate on /pre-release. Custody
  // tracking is facility/booking data that many facility-adjacent roles read;
  // the pre-release reentry workspace is a narrower job: the CF Care Manager
  // owns it, the MAT prescriber orders in it (Build 3), the screening
  // clinicians score AUDIT-10/DAST-10/AHC-HRSN in it (Build 2), the clinical
  // coordinator routes it, the receiving ECM Provider is the continuity point
  // (`receivingEcmStaffId`), and sys_admin supports it.
  //
  // This is deliberately a MATRIX row, not a role list in the nav registry, so
  // the existing `canSeeNavEntry` gate model and `canAccess` helper keep being
  // the only "who can see this" mechanism in the app. It grants VISIBILITY of
  // the workspace only — every action inside it still re-checks its own class
  // (meds_erx for MAT, screeners_sud for Part 2 content, custody_tracking for
  // facility data), so Builds 1-4 permission logic is untouched.
  | "pre_release"
  // §Facility & Custody reorg — physical controlled-substance stock and
  // chain-of-custody reconciliation. Deliberately NOT `custody_tracking`
  // (facility/incarceration) and NOT `meds_erx` (prescribing/transmission):
  // an outpatient site counts a narcotics box without doing facility work.
  | "controlled_substance_custody"
  | "population_health"
  | "crisis_queue"
  | "patient_messaging"
  | "provider_requests"
  // §Front-door community inquiries — NON-clinical "what brings you here"
  // notes from people who are not patients. Its own class so it never
  // inherits chart permissions: the free text may still mention MH/SUD, so
  // it is read by coordination roles, not by billing.
  | "community_inquiries"
  | "worklist"
  | "note_templates"
  | "catalog_governance"
  // §EHR audit Phase 1f — PLATFORM administration: the system-wide audit trail
  // (/admin-audit) and third-party integration health (/admin-vendors). This
  // closes the swim-lane audit's Tab 7 finding (no dedicated audit /
  // platform-config class) instead of compounding the documented workaround of
  // borrowing `catalog_governance`. Deliberately separate from every clinical
  // config class: the audit trail spans EVERY class (including Part 2 reads),
  // so it must never be reachable as a side effect of a drug-catalog grant.
  | "platform_administration"
  | "scheduling_rules"
  // §Group sessions — managing the group itself (schedule, roster, attendance).
  | "group_sessions"
  // §Group sessions — the clinical documentation produced by a group.
  | "group_notes"
  // §Quality pass Group A — who supervises whom. Workforce configuration, not
  // patient data: it decides billability of supervised roles, so it sits in
  // the same config tier as note_templates / scheduling_rules rather than
  // getting a parallel permission system of its own.
  | "staff_supervision"
  // §Front-door Phase 3 (Tier 2) — operating the sign-up / code-redemption
  // front door ON SOMEONE'S BEHALF. A record class, not a new permission
  // concept: it slots into the same matrix, the same canAccess() call and the
  // same nav gate as every other surface.
  | "assisted_signup"
  // §Content Management admin tooling — patient-facing educational content
  // (Library lessons, Recovery-module lessons) as MANAGED content rather than
  // hardcoded TypeScript. Its own class, in the same config tier as
  // `note_templates` / `catalog_governance` / `scheduling_rules`: it is not
  // patient data, it is what every patient is SHOWN. `write` = may AUTHOR and
  // submit a draft; APPROVING and publishing is narrower still and is
  // expressed the way `PROTOCOL_MANAGE_ROLES` already expresses that kind of
  // rule — see CONTENT_APPROVER_ROLES below.
  | "content_authoring"
  // §EHR audit Phase 1b — clinical sign-off governance for PATIENT-FACING
  // CLINICAL WORDING that is not a Library lesson: today the translated
  // medication-refusal risk disclosures reviewed in RiskTextReviewPanel.
  // Its own class because no existing one fits honestly: `content_authoring`
  // is deliberately wide (peers, CHWs, care managers author lessons) and must
  // not confer clinical disclosure sign-off; `meds_erx` is prescribing and
  // transmission, not wording governance; `catalog_governance` is the drug /
  // frequency catalog. Same config tier as note_templates.
  | "clinical_text_governance";


export type AccessLevel = "none" | "read" | "write" | "summary" | "consent_gated";

// Matrix mirrors §4b. `consent_gated` = read/write allowed only when the
// matching Part-2 consent is currently granted.
const MATRIX: Record<RecordClass, Partial<Record<StaffRole, AccessLevel>>> = {
  // 26 Oct intake role: account support is independent, not inherited by intake.
  account_support: { sys_admin: "write" },
  demographics: {
    ecm_provider: "write",
    // §v3.0 — new roles. Each grant below was decided per-class, not copied
    // from ecm_provider: cf_care_manager only needs identity to work the
    // pre-release list; clinical_trainee / medical_assistant read only.
    cf_care_manager: "read",
    // §Chart registry — matches DEMOGRAPHICS_EDITOR_ROLES (demographics.ts):
    // the SUD counselor reads; coordinator and sys_admin edit.
    sud_counselor: "read",
    clinical_trainee: "read",
    medical_assistant: "read",
    peer_specialist: "read",
    community_health_worker: "read",
    therapist: "read",
    pmhnp: "read",
    billing: "read",
    billing_coordinator: "read",
    // §Permission fix — identity on records these roles already act on.
    // clinical_coordinator dispositions crisis-queue entries and sys_admin
    // corrects consent records; both need to read WHO the patient is. Read
    // only: neither role edits demographics.
    clinical_coordinator: "write",
    sys_admin: "write",
  },
  screeners_mh: {
    ecm_provider: "write",
    sud_counselor: "read",
    clinical_trainee: "read",
    peer_specialist: "read",
    therapist: "read",
    pmhnp: "read",
  },
  screeners_sud: {
    // Kept consent_gated: the Part 2 message-masking/flag model (earlier
    // product decision) keys on this. The ASAM section/action additionally
    // applies SUD_MED_WITHHELD_ROLES via roleSeesAsamSection, so ECM never
    // sees ASAM even with consent.
    ecm_provider: "consent_gated",
    peer_specialist: "consent_gated",
    // DMC-ODS: the SUD counselor IS the treating provider for this material,
    // so they sit with therapist/pmhnp, not with coordination roles.
    sud_counselor: "read",
    // A trainee treats under supervision but is not the consent holder.
    clinical_trainee: "consent_gated",
    medical_assistant: "none",
    cf_care_manager: "none",
    // Policy: therapist and pmhnp are both direct treating clinicians with a
    // legitimate clinical need to know SUD status without a separate consent
    // gate. ecm_provider/peer_specialist stay gated because care coordination
    // is not clinical treatment — that distinction is the actual line.
    therapist: "read",
    pmhnp: "read",
  },
  psych_eval: {
    ecm_provider: "read",
    peer_specialist: "read",
    therapist: "read",
    pmhnp: "write",
    sud_counselor: "read",
    clinical_trainee: "read",
  },
  care_plan: {
    // §Chart registry — matches PLAN_EDIT_ROLES (structuredCarePlan.ts):
    // ECM / care manager edit non-SUD items; coordinator reads (reassigns
    // owners only); sys_admin reads, no clinical editing.
    ecm_provider: "write",
    clinical_coordinator: "read",
    sys_admin: "read",
    peer_specialist: "read",
    therapist: "write",
    pmhnp: "write",
    sud_counselor: "write",
    clinical_trainee: "write",
    cf_care_manager: "write",
  },
  // A trainee may AUTHOR a note; they can never self-sign it —
  // NOTE_SELF_SIGN_ROLES (ehr.ts) is pmhnp/therapist only, so every trainee
  // note routes for cosignature by construction.
  therapy_notes: {
    therapist: "write",
    pmhnp: "read",
    // Draft — pending executive RBAC review: ECM sees clinical-note METADATA
    // only (date, type, author, status, visit); bodies via noteBodyRestricted().
    ecm_provider: "summary",
    sud_counselor: "read",
    clinical_trainee: "write",
  },
  // Medical assistant reads the med list to support MAT administration; the
  // write path is NOT here — see canRecordMatAdministration(), which also
  // requires an active supervision link.
  meds_erx: {
    pmhnp: "write",
    therapist: "read",
    ecm_provider: "read",
    medical_assistant: "read",
    clinical_trainee: "read",
  },
  telehealth_room: {
    pmhnp: "write",
    therapist: "write",
    sud_counselor: "write",
    clinical_trainee: "read",
    ecm_provider: "read",
    peer_specialist: "none" as AccessLevel,
  },
  sdoh: {
    ecm_provider: "write",
    peer_specialist: "write",
    community_health_worker: "write",
    therapist: "write",
    pmhnp: "write",
    sud_counselor: "write",
    cf_care_manager: "write",
  },
  self_help: {
    ecm_provider: "write",
    peer_specialist: "write",
    therapist: "write",
    pmhnp: "write",
    sud_counselor: "write",
  },
  sud_treatment: {
    pmhnp: "write",
    therapist: "consent_gated",
    sud_counselor: "write",
    clinical_trainee: "consent_gated",
    ecm_provider: "consent_gated",
    peer_specialist: "consent_gated",
    billing: "consent_gated",
  },
  case_notes: {
    ecm_provider: "write",
    peer_specialist: "read",
    community_health_worker: "read",
    therapist: "read",
    pmhnp: "read",
    sud_counselor: "write",
    clinical_trainee: "write",
    cf_care_manager: "read",
  },
  peer_notes: { peer_specialist: "write", ecm_provider: "read", therapist: "read", pmhnp: "read" },
  chw_notes: {
    community_health_worker: "write",
    ecm_provider: "read",
    therapist: "read",
    pmhnp: "read",
    clinical_coordinator: "read",
  },
  documents: {
    ecm_provider: "write",
    therapist: "read",
    pmhnp: "read",
    sud_counselor: "read",
    cf_care_manager: "read",
    medical_assistant: "read",
  },
  // §Phase 7a — billing and billing_coordinator are one billing function
  // (to be merged into a single role); every class grants them the same level.
  // sys_admin reads (view-only /billing and /admin-claims); never writes.
  billing: { billing: "write", billing_coordinator: "write", sys_admin: "read" },
  consent_ledger: {
    // §ASCMI — consent capture must be writable by someone. ecm_provider
    // writes because they are the role that actually sits with the patient
    // and captures the form; sys_admin writes for correction/administration.
    // Clinical roles stay read-only: reading the ledger is need-to-know,
    // authoring a legal consent instrument is not part of their workflow.
    ecm_provider: "write",
    peer_specialist: "read",
    therapist: "read",
    pmhnp: "read",
    billing: "read",
    billing_coordinator: "read",
    sys_admin: "write",
    // DMC-ODS consent is captured at intake by the counselor too.
    sud_counselor: "write",
    cf_care_manager: "read",
    // Coordinators merge records and must re-confirm carried-over consents (read only).
    clinical_coordinator: "read",
  },
  /**
   * §ASCMI psychotherapy-notes tier — SCAFFOLD ONLY, DEFAULT DENY.
   * Strictly more restrictive than `screeners_sud` / `sud_treatment`: no role
   * has access, and SUD consent does NOT unlock it (ASCMI does not authorize
   * release of psychotherapy notes). Deliberately UNAPPLIED to any real
   * template or note today — deciding which documentation qualifies is a
   * clinical-content call and needs clinical author sign-off (Christi /
   * Dr. Bagga) before anything is tagged with it.
   */
  psychotherapy_notes: {},
  // Clinical record layer (BaggaEMR mirror). Prescribers (pmhnp) and
  // therapists write; ecm_provider / peer_specialist can read for
  // coordination; billing reads Problems only for claim coding.
  problems: {
    pmhnp: "write",
    therapist: "write",
    ecm_provider: "read",
    peer_specialist: "read",
    billing: "read",
    billing_coordinator: "read",
    clinical_coordinator: "read",
    sud_counselor: "read",
    clinical_trainee: "read",
    medical_assistant: "read",
  },
  allergies: {
    pmhnp: "write",
    therapist: "write",
    ecm_provider: "read",
    peer_specialist: "read",
    clinical_coordinator: "read",
    sud_counselor: "read",
    clinical_trainee: "read",
    medical_assistant: "read",
  },
  alerts: {
    pmhnp: "write",
    therapist: "write",
    ecm_provider: "write",
    peer_specialist: "read",
    clinical_coordinator: "read",
    sud_counselor: "read",
    clinical_trainee: "read",
    medical_assistant: "read",
  },
  // §Adelante Journey Phase 7 — safety plan. Read is deliberately WIDE across
  // roles that respond to a crisis (peers included — a peer specialist on the
  // phone at 2am is exactly who needs the patient's own plan). Write is for
  // the roles that build the plan WITH the patient; billing roles get nothing
  // — this is never claim data.
  safety_plan: {
    pmhnp: "write",
    therapist: "write",
    ecm_provider: "write",
    sud_counselor: "write",
    clinical_coordinator: "write",
    peer_specialist: "read",
    community_health_worker: "read",
    cf_care_manager: "read",
    clinical_trainee: "read",
    medical_assistant: "read",
    sys_admin: "read",
    billing: "none",
    billing_coordinator: "none",
  },
  eligibility: {
    ecm_provider: "write",
    billing: "write",
    billing_coordinator: "write",
    therapist: "read",
    pmhnp: "read",
    clinical_coordinator: "read",
    sud_counselor: "read",
    cf_care_manager: "read",
  },
  care_coordination: {
    ecm_provider: "write",
    therapist: "write",
    pmhnp: "write",
    peer_specialist: "read",
    community_health_worker: "write",
    clinical_coordinator: "read",
    sud_counselor: "write",
    // Reentry coordination is the CF Care Manager's entire job.
    cf_care_manager: "write",
    clinical_trainee: "read",
  },
  // §Custody tracking (bookings, housing moves, released search). Custody
  // status is coordination data, so case management owns the write path;
  // clinicians read it for context. Billing gets nothing — custody history is
  // not claim-relevant and would be an unnecessary exposure.
  custody_tracking: {
    ecm_provider: "write",
    clinical_coordinator: "write",
    therapist: "read",
    pmhnp: "read",
    peer_specialist: "read",
    sys_admin: "read",
    // Pre-release work happens inside the facility record.
    cf_care_manager: "write",
  },
  // §Pre-release build 5 — see the RecordClass comment above.
  pre_release: {
    // Owner of the D90→0 list.
    cf_care_manager: "write",
    // Receiving-side continuity point; the page further narrows an ECM
    // Provider to episodes where they are the named receiving provider.
    ecm_provider: "write",
    // MAT prescriber (Build 3 reuses the `meds_erx` write gate to sign).
    pmhnp: "write",
    // Screening clinicians (Build 2 instruments).
    therapist: "read",
    sud_counselor: "read",
    // Routing / coverage.
    clinical_coordinator: "read",
    sys_admin: "read",
  },
  // §Facility & Custody reorg — controlled-substance custody: physical stock
  // on hand and chain-of-custody reconciliation (Shift count).
  //
  // Why this is its own class and not one of the two it sits between:
  //  - NOT `meds_erx`: that class is e-prescribing / pharmacy routing — an
  //    order leaving the building. A shift count is about the tangible stock
  //    in the cabinet; the two can be granted to different people.
  //  - NOT `custody_tracking`: in this codebase "custody" there means
  //    facility/incarceration (Released Patient Search, Facilities, booking
  //    episodes). Gating Shift count on it would force facility permissions
  //    onto an outpatient site that merely reconciles sample/emergency stock,
  //    breaking the exact use case this separation exists to serve.
  //
  // Starting grant deliberately MIRRORS `meds_erx` exactly, so this reorg is
  // access-neutral: nobody who can reach Shift count today loses it. Tightening
  // it (e.g. dropping the two read roles, or adding clinical_coordinator as a
  // second signer) is a follow-on policy decision, not a refactor side effect.
  controlled_substance_custody: {
    pmhnp: "write",
    therapist: "read",
    ecm_provider: "read",
    // §v3.0 — kept exactly mirrored to `meds_erx` for the new roles too, so
    // the access-neutrality invariant in navSections.test.ts still holds.
    medical_assistant: "read",
    clinical_trainee: "read",
  },
  // §Population health dashboards. Cross-patient aggregate + drill-down to
  // PHI, and revenue-adjacent, so this is read-by-default and write only for
  // the two roles that own reporting configuration:
  //  - sys_admin: config/oversight tier (KPI targets are operational config,
  //    not clinical authorship), consistent with its role elsewhere.
  //  - clinical_coordinator: owns the clinical targets themselves.
  // Billing + billing_coordinator read (revenue-relevant), clinical roles
  // read, peer_specialist gets nothing — aggregate cross-patient exposure is
  // outside the peer scope everywhere else in this matrix.
  population_health: {
    sys_admin: "write",
    clinical_coordinator: "write",
    // §Privacy P1 — billing roles see claim-level data only: no population
    // health dashboards (named clinical drill-downs, CalOMS, engagement).
    billing: "none",
    billing_coordinator: "none",
    pmhnp: "read",
    therapist: "read",
    ecm_provider: "read",
    peer_specialist: "none",
  },
  // §Clinical documentation templates. Authoring a template is clinical
  // configuration, not patient care: sys_admin + clinical_coordinator write,
  // documenting clinicians read (they pick templates when writing notes),
  // billing gets nothing — template structure is not claim data.
  // §EHR audit Phase 2b — "write" now means specifically "may author the
  // SHARED tiers" (System / Discipline). "read" means the library is visible
  // and the person may keep their own PERSONAL copies, which is documentation
  // rather than configuration. sud_counselor and clinical_trainee were added
  // for exactly that reason: they write notes, so they need a personal tier.
  note_templates: {
    sys_admin: "write",
    clinical_coordinator: "write",
    pmhnp: "read",
    therapist: "read",
    ecm_provider: "read",
    peer_specialist: "read",
    sud_counselor: "read",
    clinical_trainee: "read",
  },
  // §Content Management — WHO MAY AUTHOR patient-facing educational content.
  // Deliberately WIDER than note_templates on the author side: the people who
  // know what a lesson needs to say are the ones sitting with patients
  // (SUD counselors, peers, CHWs, care managers), not only config owners. It
  // is safe to be wide here precisely because authoring cannot publish —
  // CONTENT_APPROVER_ROLES gates that, and the store enforces it.
  content_authoring: {
    sys_admin: "write",
    clinical_coordinator: "write",
    pmhnp: "write",
    therapist: "write",
    sud_counselor: "write",
    peer_specialist: "write",
    community_health_worker: "write",
    ecm_provider: "write",
    cf_care_manager: "write",
    clinical_trainee: "write",
    medical_assistant: "read",
    billing: "none",
  },
  // §EHR audit Phase 1b — risk-text translation sign-off. Write set is an
  // exact, deliberate reproduction of the hardcoded expression it replaces
  // (sys_admin, clinical_coordinator, and the one `meds_erx: write` role,
  // pmhnp). Read = the meds_erx readers, who could already see the panel
  // read-only; everyone else defaults to none.
  clinical_text_governance: {
    sys_admin: "write",
    clinical_coordinator: "write",
    pmhnp: "write",
    therapist: "read",
    ecm_provider: "read",
    medical_assistant: "read",
    clinical_trainee: "read",
    billing: "none",
  },

  // §Admin governance — frequency catalog + local RxNav suppressions.
  // §EHR audit Phase 1f — narrowed to clinical config owners + super admin.
  // The former `read` grants to pmhnp / therapist / ecm_provider existed so
  // prescribers could see WHY a product is missing from search; that reason is
  // already shown inline by CatalogPicker (the "hidden by local suppression"
  // block reads the suppression list directly, with no `canAccess` gate), so
  // the read grant bought nothing but reach into an admin configuration
  // surface. Removed for all three.
  catalog_governance: {
    sys_admin: "write",
    clinical_coordinator: "write",
    pmhnp: "none",
    therapist: "none",
    ecm_provider: "none",
    peer_specialist: "none",
    billing: "none",
