// ----- Seeded staff roster -----
// Adelante models authorship as a named person, not a role string. Every
// role has at least one seeded staff member so there is always a real
// identity available for authorship + per-record authorization.
export interface StaffMember {
  id: string;
  name: string;
  role: StaffRole;
  /** Held roles, never unioned; permissions use the one acting role. */
  additionalRoles?: StaffRole[];
  credential?: string;
  /** Links this staff member to a clinical provider record in AdelanteEHR. */
  clinicianId?: string;
  /**
   * §EHR audit Phase 1g — links this staff member to a `CaseManager` record in
   * AdelanteEHR (`patient.caseManagerId`). Only the people who actually carry a
   * non-clinical caseload have one; it is how "assigned to me" on
   * /case-manager resolves. A VIEW-scoping link, not an access grant.
   */
  caseManagerId?: string;
  /**
   * §v3.0 supervision — id of the LPHA-tier StaffMember who supervises this
   * person. A real, queryable field (not a comment): roles in
   * SUPERVISION_REQUIRED_ROLES are not billable without it, and the
   * MAT-administration capability check reads it directly.
   */
  supervisedBy?: string;
  /**
   * §v3.0 CF Care Manager dual access mode.
   *  - "direct": facility/contract staff who log in themselves.
   *  - "proxy": a CF Care Manager who is NOT a platform user; their task-list
   *    activity is entered on their behalf by the receiving ECM Provider.
   * Only meaningful for `cf_care_manager`.
   */
  accessMode?: "direct" | "proxy";
  /** Long display form, e.g. "Dr. Riley Sample, M.D." (header). */
  fullName?: string;
  /**
   * §Batch E — one person, one identity, several role assignments. `role` is
   * the default; the switcher picks the active one and audit records it.
   * Absent = one assignment (`role`). In-facility assignments hide when the
   * in-facility flag is off.
   */
  roleAssignments?: RoleAssignment[];
  /** §Batch C4 — false = inactive (never auto-assigned as a crisis owner). */
  active?: boolean;
  /** §B6 — sites this person is assigned to (admin-set, not an access grant). */
  siteIds?: string[];
  /** §B6 — when `active` was last set to false, via staffLifecycle.ts. */
  deactivatedAt?: string;
  /** Staff dedupe keys. */
  npi?: string;
  email?: string;
}
export interface RoleAssignment {
  role: StaffRole;
  accessMode?: "direct" | "proxy";
  inFacility?: boolean;
}
/** Role assignments a person can act in right now (in-facility ones only when the flag is on). */
export function roleAssignmentsOf(m: StaffMember | undefined, opts: { includeHidden?: boolean } = {}): RoleAssignment[] {
  if (!m) return [];
  const legacy = m.roleAssignments ?? [{ role: m.role, accessMode: m.accessMode }];
  // Explicit additionalRoles replaces legacy assignments, so removing a held role really removes it.
  const list: RoleAssignment[] = m.additionalRoles === undefined ? legacy : [...new Set([m.role, ...m.additionalRoles])].map(role => legacy.find(a => a.role === role) ?? {role});
  return opts.includeHidden ? list : list.filter((a) => !a.inFacility || isFeatureEnabled("in_facility"));
}
export function hasRoleAssignment(m: StaffMember | undefined, role: StaffRole, opts: { includeHidden?: boolean } = {}): boolean {
  return roleAssignmentsOf(m, opts).some((a) => a.role === role);
}
/** Staff dedupe: same NPI or same email = same person. Returns the existing identity. */
export function findDuplicateStaff(input: { npi?: string; email?: string }, roster: StaffMember[] = STAFF_ROSTER): StaffMember | undefined {
  const npi = input.npi?.replace(/\D/g, "");
  const email = input.email?.trim().toLowerCase();
  return roster.find((m) => (npi && m.npi?.replace(/\D/g, "") === npi) || (email && m.email?.trim().toLowerCase() === email));
}

