/**
 * §Batch E1 — adds a staff member through one audited path (used by demo
 * seeds too; there is no identity backend yet). sys_admin only.
 */
export function addStaffMember(actor: { role: StaffRole; staffId?: string }, member: StaffMember): StaffMember {
  if (actor.role !== "sys_admin") throw new Error("Only a system admin can add staff.");
  const existing = STAFF_ROSTER.find((s) => s.id === member.id);
  if (existing) return existing;
  STAFF_ROSTER.push(member);
  AdelanteEHR.recordActionEvent({
    action: "staff.added",
    actorRole: actor.role,
    actorId: actor.staffId,
    detail: { staffId: member.id, role: member.role },
  });
  return member;
}

/**
 * §ASCMI — which structured consent category unlocks each consent-gated
 * record class. Placeholder categories (see CONSENT_CATEGORIES in ehr.ts).
 */
const CONSENT_GATE_CATEGORY: Partial<Record<RecordClass, ConsentCategory>> = {
  screeners_sud: "sud_treatment",
  sud_treatment: "sud_treatment",
  // Only SUD-clinical group notes ever reach this class (noteGateClass()
  // routes the two non-SUD categories away from it), so `sud_treatment` is
  // the honest mapping. Telehealth/confidentiality consents gate
  // PARTICIPATION, not record visibility, and live in the occurrence flow.
  group_notes: "sud_treatment",
};

/**
 * Which record class gates a given note. One place, so masking can never
 * diverge between the chart, print/export and autofill.
 */
export function noteGateClass(
  note: Pick<ProgressNote, "category" | "restrictedTier"> &
    Partial<Pick<ProgressNote, "groupRef">>,
): RecordClass | undefined {
  if (note.restrictedTier === "psychotherapy_notes") return "psychotherapy_notes";
  if (note.category === "sud") return "screeners_sud";
  if (note.category === "group") {
    // §Group notes — category-aware. Only `sud_clinical_preauth` is genuine
    // 42 CFR Part 2 treatment content, so only it routes through the
    // consent-gated `group_notes` class. `skills_education` and
    // `open_psychoeducational` are not SUD-sensitive: they fall back to the
    // SAME tier ordinary (non-Part 2) progress notes already use — no record
    // class at all, i.e. chart access governs. That is the existing tier, not
    // a new one. An unstamped legacy group note keeps the conservative
    // Part 2 gate.
    const cat = note.groupRef?.category;
    if (cat === "skills_education" || cat === "open_psychoeducational") return undefined;
    return "group_notes";
  }
  return undefined;
}

/**
 * The physician carries every PMHNP grant; the matrix stores it once under
 * `pmhnp` so the two can never drift apart.
 */
export function permissionRole(role: StaffRole): StaffRole {
  return role === "physician" ? "pmhnp" : role;
}

/** Prescribers: may sign orders, approve refills and record CURES. */
export const PRESCRIBER_ROLES: StaffRole[] = ["physician", "pmhnp"];
export const isPrescriberRole = (r: string) => (PRESCRIBER_ROLES as string[]).includes(r);

export function canAccess(
  role: StaffRole,
  cls: RecordClass,
  patient?: Patient,
): { level: AccessLevel; locked: boolean; reason?: string } {
  if (role === "clinical_coordinator" && cls === "psychotherapy_notes") {
    const allowed = coordinatorSudCanRead({ role }, patient, "counseling_notes");
    return { level: allowed ? "read" : "none", locked: !allowed };
  }
  const level = MATRIX[cls]?.[permissionRole(role)] ?? "none";
  // 28 Oct access-rules reconciliation: reason-only access never supplies the internal-use basis.
  // Specific written evidence must name the class; standard TPO remains packet-only here.
  if (patient && ["screeners_sud", "sud_treatment", "group_notes"].includes(cls) && level !== "none" && chartPart2Basis(role, getActingRole() === role ? getActingStaff()?.id : undefined, patient.id).reasonOnly) {
    const covered = consentGate(patient.id, { types: ["part2_specific_written"], recipients: PROGRAM_RECIPIENTS, purposes: ["treatment", "tpo"], item: cls }, () => false);
    return covered ? { level: level === "consent_gated" ? "read" : level, locked: false } : { level: "none", locked: true, reason: "42 CFR Part 2 — consent required" };
  }
  // Intake collects paperwork, never reads assessment scores or treatment content.
  if (role === "intake_coordinator" && (cls === "screeners_sud" || cls === "sud_treatment")) return {level:"none",locked:true,reason:"42 CFR Part 2 — consent required"};
  if (level === "consent_gated") {
    // LIVE check against the structured ConsentRecord — never cached. Expiry
    // and revocation therefore stop access at the next call, with no other
    // code path needing to be notified.
    const category = CONSENT_GATE_CATEGORY[cls] ?? "sud_treatment";
    const granted = patient
      ? AdelanteEHR.isConsentCategoryAuthorized(patient.id, category)
      : false;
    return granted
      ? { level: "read", locked: false }
      : { level: "none", locked: true, reason: "42 CFR Part 2 — consent required" };
  }
  return { level, locked: level === "none" };
}

